/**
 * React Hook for Claude Code WebSocket (Bidirectional)
 *
 * Provides real-time bidirectional communication with Claude Code agents.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { createClaudeCodeEventState, isClaudeCodeCoreEvent, reduceClaudeCodeEventState, } from "./event-state-reducer.js";
import { NETWORK_ERROR, REQUEST_ERROR } from "../../../errors/error-registry/server.js";
/** Default delay before reconnecting after disconnect */
const DEFAULT_RECONNECT_DELAY_MS = 1_000;
/** Default interval for WebSocket ping messages */
const DEFAULT_PING_INTERVAL_MS = 30_000;
/**
 * React hook for bidirectional Claude Code streaming
 *
 * @example
 * ```tsx
 * function AgentController({ runId }: { runId: string }) {
 *   const {
 *     isRunning,
 *     text,
 *     pendingApprovals,
 *     cancel,
 *     approve,
 *     reject,
 *   } = useClaudeCodeWebSocket({
 *     url: '/api/workflows/ws',
 *     runId,
 *   });
 *
 *   return (
 *     <div>
 *       <pre>{text}</pre>
 *
 *       {pendingApprovals.map(pa => (
 *         <div key={pa.toolCallId}>
 *           <p>Approve {pa.toolName}?</p>
 *           <pre>{JSON.stringify(pa.input, null, 2)}</pre>
 *           <button onClick={() => approve(pa.toolCallId)}>Approve</button>
 *           <button onClick={() => reject(pa.toolCallId)}>Reject</button>
 *         </div>
 *       ))}
 *
 *       {isRunning && (
 *         <button onClick={() => cancel()}>Cancel</button>
 *       )}
 *     </div>
 *   );
 * }
 * ```
 */
export function useClaudeCodeWebSocket(options) {
    const { url, runId, autoConnect = true, autoReconnect = true, maxReconnectAttempts = 5, reconnectDelay = DEFAULT_RECONNECT_DELAY_MS, pingInterval = DEFAULT_PING_INTERVAL_MS, onEvent, onConnect, onDisconnect, onError, onComplete, onApprovalRequest, onInputRequest, } = options;
    const [state, setState] = useState({
        ...createClaudeCodeEventState(),
        isConnected: false,
        isCancelled: false,
        pendingApprovals: [],
        pendingInput: null,
    });
    const socketRef = useRef(null);
    const reconnectAttemptsRef = useRef(0);
    const reconnectTimeoutRef = useRef(null);
    const pingIntervalRef = useRef(null);
    // Process incoming event
    const processEvent = useCallback((event) => {
        onEvent?.(event);
        setState((prev) => {
            const newState = isClaudeCodeCoreEvent(event)
                ? reduceClaudeCodeEventState(prev, event)
                : { ...prev };
            switch (event.type) {
                case "complete":
                    newState.pendingApprovals = [];
                    newState.pendingInput = null;
                    onComplete?.(event.result);
                    break;
                case "cancelled":
                    newState.isRunning = false;
                    newState.isCancelled = true;
                    newState.pendingApprovals = [];
                    newState.pendingInput = null;
                    break;
                case "approval_request": {
                    const approval = {
                        toolCallId: event.toolCallId,
                        toolName: event.toolName,
                        input: event.input,
                        reason: event.reason,
                        timeout: event.timeout,
                        requestedAt: Date.now(),
                    };
                    newState.pendingApprovals = [...prev.pendingApprovals, approval];
                    onApprovalRequest?.(approval);
                    break;
                }
                case "input_request": {
                    const inputReq = {
                        prompt: event.prompt,
                        defaultValue: event.defaultValue,
                        timeout: event.timeout,
                        requestedAt: Date.now(),
                    };
                    newState.pendingInput = inputReq;
                    onInputRequest?.(inputReq);
                    break;
                }
                case "pong":
                    // Keepalive response, no state change needed
                    break;
            }
            return newState;
        });
    }, [onEvent, onComplete, onApprovalRequest, onInputRequest]);
    // Send command to server
    const sendCommand = useCallback((command) => {
        const socket = socketRef.current;
        if (!socket || socket.readyState !== WebSocket.OPEN) {
            console.warn("[useClaudeCodeWebSocket] Socket not open");
            return;
        }
        socket.send(JSON.stringify({
            ...command,
            timestamp: Date.now(),
            runId,
        }));
    }, [runId]);
    // Connect to WebSocket
    const connect = useCallback(() => {
        if (socketRef.current) {
            socketRef.current.close();
        }
        const wsUrl = `${url}?runId=${encodeURIComponent(runId)}`;
        const socket = new WebSocket(wsUrl);
        socket.onopen = () => {
            setState((prev) => ({ ...prev, isConnected: true }));
            reconnectAttemptsRef.current = 0;
            onConnect?.();
            // Start ping interval
            if (pingInterval > 0) {
                pingIntervalRef.current = globalThis.setInterval(() => {
                    sendCommand({ type: "ping" });
                }, pingInterval);
            }
        };
        socket.onmessage = (e) => {
            try {
                const parsed = JSON.parse(e.data);
                if (!parsed || typeof parsed !== "object")
                    return;
                const event = parsed;
                processEvent(event);
            }
            catch (error) {
                console.error("[useClaudeCodeWebSocket] Failed to parse event:", error);
            }
        };
        socket.onclose = () => {
            setState((prev) => ({ ...prev, isConnected: false }));
            onDisconnect?.();
            // Clear ping interval
            if (pingIntervalRef.current) {
                clearInterval(pingIntervalRef.current);
                pingIntervalRef.current = null;
            }
            // Attempt reconnect
            if (autoReconnect &&
                reconnectAttemptsRef.current < maxReconnectAttempts) {
                reconnectAttemptsRef.current++;
                reconnectTimeoutRef.current = globalThis.setTimeout(() => {
                    connect();
                }, reconnectDelay * reconnectAttemptsRef.current);
            }
            else if (reconnectAttemptsRef.current >= maxReconnectAttempts) {
                onError?.(REQUEST_ERROR.create({ detail: "Connection failed after max retries" }));
            }
        };
        socket.onerror = () => {
            onError?.(NETWORK_ERROR.create({ detail: "WebSocket error" }));
        };
        socketRef.current = socket;
    }, [
        url,
        runId,
        processEvent,
        sendCommand,
        autoReconnect,
        maxReconnectAttempts,
        reconnectDelay,
        pingInterval,
        onConnect,
        onDisconnect,
        onError,
    ]);
    // Disconnect from WebSocket
    const disconnect = useCallback(() => {
        if (reconnectTimeoutRef.current) {
            clearTimeout(reconnectTimeoutRef.current);
            reconnectTimeoutRef.current = null;
        }
        if (pingIntervalRef.current) {
            clearInterval(pingIntervalRef.current);
            pingIntervalRef.current = null;
        }
        if (socketRef.current) {
            socketRef.current.close();
            socketRef.current = null;
        }
        setState((prev) => ({ ...prev, isConnected: false }));
    }, []);
    // Cancel agent execution
    const cancel = useCallback((reason) => {
        const command = {
            type: "cancel",
            reason,
        };
        sendCommand(command);
    }, [sendCommand]);
    // Approve a tool call
    const approve = useCallback((toolCallId) => {
        sendCommand({ type: "approve", toolCallId });
        setState((prev) => ({
            ...prev,
            pendingApprovals: prev.pendingApprovals.filter((pa) => pa.toolCallId !== toolCallId),
        }));
    }, [sendCommand]);
    // Reject a tool call
    const reject = useCallback((toolCallId, reason) => {
        sendCommand({ type: "reject", toolCallId, reason });
        setState((prev) => ({
            ...prev,
            pendingApprovals: prev.pendingApprovals.filter((pa) => pa.toolCallId !== toolCallId),
        }));
    }, [sendCommand]);
    // Send user input
    const sendInput = useCallback((content) => {
        sendCommand({ type: "input", content });
        setState((prev) => ({ ...prev, pendingInput: null }));
    }, [sendCommand]);
    // Auto-connect on mount
    useEffect(() => {
        if (autoConnect) {
            connect();
        }
        return () => {
            disconnect();
        };
    }, [autoConnect, connect, disconnect]);
    return {
        ...state,
        connect,
        disconnect,
        cancel,
        approve,
        reject,
        sendInput,
    };
}
